def push_advice_to_cloud(device_id: str, session_id: str, advice: str):
    """
    推送极端情绪建议到云端

    这是独立推送，不是对pushData的响应
    """
    try:
        # 生成msgId（使用时间戳）
        msg_id = str(int(time.time() * 1000))

        payload = {
            "value": [{
                "msgId": msg_id,
                "status": 22,  # 22-音频返回结果（极端情绪建议）
                "msgEvent": 1,  # 1-音频结果
                "response": {
                    "advice": advice
                }
            }],
            "deviceId":
            device_id,
            "sessionId":
            session_id,
            "timestamp":
            str(int(time.time() * 1000))
        }

        resp = requests.post(CLOUD_PUSH_RESULT_URL, json=payload, timeout=10)
        print(f"[极端情绪] 推送建议到云端: {resp.status_code}")

        if resp.status_code == 200:
            result = resp.json()
            if result.get("status") == 10:
                print(f"[极端情绪] 云端确认接收")
            else:
                print(f"[极端情绪] 云端接收失败: {result}")

    except Exception as e:
        print(f"[极端情绪] 推送失败: {e}")

